import { AboutPanel, InfoScreen } from '@drizztdourden08/tessera';

const AboutScreen = ({ onClose }: { onClose: () => void }) => (
  <InfoScreen title="About" onClose={onClose} footer="Names and marks belong to their owners.">
    <AboutPanel title="Relic of the Past" brand="rotp" rows={[{ label: 'Version', value: '0.9.2' }]} />
  </InfoScreen>
);

import type { ReactNode } from 'react';
import { ScreenLayer } from '@drizztdourden08/tessera';

const KioskScreen = ({ children }: { children: ReactNode }) => (
  <ScreenLayer label="Kiosk" className="kiosk-screen">
    {children}
  </ScreenLayer>
);

import { ScreenWindow, ScrollArea } from '@drizztdourden08/tessera';

const SessionsScreen = ({ onClose }: { onClose: () => void }) => (
  <ScreenWindow title="Sessions" subtitle="Profile: mira" onClose={onClose}>
    <ScrollArea>Sessions list</ScrollArea>
  </ScreenWindow>
);

import { StageScreen, Status } from '@drizztdourden08/tessera';

const Calibration = ({ onClose }: { onClose: () => void }) => (
  <StageScreen
    title="Input calibration"
    onClose={onClose}
    toolbar={<Status tone="success" variant="pill">Controller connected</Status>}
    done={{ onClick: onClose }}
  >
    Calibration steps
  </StageScreen>
);

import { Button, UtilityScreen } from '@drizztdourden08/tessera';

const UpdateCheck = ({ onClose, onInstall }: { onClose: () => void; onInstall: () => void }) => (
  <UtilityScreen
    title="Check for updates"
    onClose={onClose}
    status={{ tone: 'info', title: 'Version 0.10.0 is ready', message: 'You have 0.9.2.' }}
    footnote={{ text: 'Please report anything that stops working.', action: <Button size="sm" variant="secondary">Report an issue</Button> }}
    actions={[
      { label: 'Later', variant: 'ghost', onClick: onClose },
      { label: 'Install', variant: 'primary', onClick: onInstall },
    ]}
  />
);

import { Icon, SettingsGroupList, WorkspaceScreen } from '@drizztdourden08/tessera';
import type { SettingsGroupListSection, SideNavConfig } from '@drizztdourden08/tessera';

interface HubProps {
  config: SideNavConfig;
  active: string;
  onSelect: (id: string) => void;
  sections: SettingsGroupListSection[];
  onClose: () => void;
}

const SettingsHub = ({ config, active, onSelect, sections, onClose }: HubProps) => (
  <WorkspaceScreen
    title="Settings"
    onClose={onClose}
    nav={{ config, activeId: active, onSelect, defaultOpen: true }}
    page={{ icon: <Icon name="settings" />, title: 'General' }}
  >
    <SettingsGroupList sections={sections} />
  </WorkspaceScreen>
);
